                        f"row {record_number} has {len(row)} fields; expected {len(headers)}"
                    )
                rows.append(row)
            return headers, rows
    except CsvInsightsError:
        raise
    except csv.Error as exc:
        raise CsvInsightsError(f"malformed CSV near line {getattr(reader, 'line_num', '?')}: {exc}") from exc
